import{_ as a,o as n,a as p,b as c}from"./app.DKoEZOcr.js";const g=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"高级编程","link":"/guide/programming_guide/advanced_programming/advanced_programming"},{"text":"Aclnn算子工程化开发","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/overview"},{"text":"设计与实现","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_function_design"},{"text":"算子原型定义","link":"/guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_prototype_definition"}]},"headers":[],"relativePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_prototype_definition.md","filePath":"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_prototype_definition.md","outlineHeaders":[{"level":2,"title":"原型定义放在哪里","slug":"原型定义放在哪里","link":"#原型定义放在哪里"},{"level":2,"title":"定义OpDef类并注册算子","slug":"定义OpDef类并注册算子","link":"#定义OpDef类并注册算子"},{"level":2,"title":"定义输入和输出","slug":"定义输入和输出","link":"#定义输入和输出"},{"level":2,"title":"定义属性","slug":"定义属性","link":"#定义属性"},{"level":2,"title":"图模式下注册输出shape和dtype推导函数","slug":"图模式下注册输出shape和dtype推导函数","link":"#图模式下注册输出shape和dtype推导函数"},{"level":2,"title":"关联Host侧Tiling实现","slug":"关联Host侧Tiling实现","link":"#关联Host侧Tiling实现"},{"level":2,"title":"注册GenSimplifiedKey回调","slug":"注册GenSimplifiedKey回调","link":"#注册GenSimplifiedKey回调"},{"level":2,"title":"配置指定AI处理器的差异化配置","slug":"配置指定AI处理器的差异化配置","link":"#配置指定AI处理器的差异化配置"},{"level":3,"title":"使用OpAICoreConfig注册差异化配置","slug":"使用OpAICoreConfig注册差异化配置","link":"#使用OpAICoreConfig注册差异化配置"},{"level":3,"title":"在独立文件中注册差异化配置","slug":"在独立文件中注册差异化配置","link":"#在独立文件中注册差异化配置"},{"level":2,"title":"完整示例","slug":"完整示例","link":"#完整示例"},{"level":2,"title":"相关文档","slug":"相关文档","link":"#相关文档"}],"lastUpdated":1787886219000}'),l={name:"guide/programming_guide/advanced_programming/aclnn_operator_development/design_and_implementation/operator_prototype_definition.md"};function e(t,s,o,d,i,h){return n(),p("div",null,[...s[0]||(s[0]=[c(`<div><article class="markdown-body"><h1>算子原型定义</h1><p>本文属于基础内容，介绍如何通过算子原型定义描述算子对外暴露的接口和支持范围。本文承接<a href="./operator_function_design.html">算子功能设计</a>的结论，说明如何将功能设计中的输入输出、属性、dtype/format和Tiling函数关联落地为<code>OpDef</code>代码，并介绍图模式下的输出shape和dtype推导配置。</p><h2 id="原型定义放在哪里">原型定义放在哪里<a class="header-anchor" href="#原型定义放在哪里">​</a></h2><p>在AddCustom样例工程中，算子原型定义位于Host侧实现文件：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>op_host/add_custom.cpp
</code></pre></div><p>该文件中同时包含三类内容：</p><table><thead><tr><th>内容</th><th>作用</th></tr></thead><tbody><tr><td><code>TilingFunc</code></td><td>Host侧Tiling函数，负责计算核函数（Kernel）启动和分块参数</td></tr><tr><td><code>InferShape</code>、<code>InferDataType</code></td><td>图模式下的输出shape和dtype推导函数，仅在需要支持图模式时编写</td></tr><tr><td><code>class AddCustom : public OpDef</code></td><td>算子原型定义，描述输入、输出、属性、Tiling关联</td></tr></tbody></table><p>本文重点讲<code>class AddCustom : public OpDef</code>中的原型定义内容，同时说明它和Tiling函数之间的连接关系，并补充图模式下关联推导函数的方法。</p><h2 id="定义OpDef类并注册算子">定义OpDef类并注册算子<a class="header-anchor" href="#定义OpDef类并注册算子">​</a></h2><p>算子原型通过一个继承自<code>OpDef</code>的C++类承载。类名通常与算子类型保持一致。AddCustom的算子类型为<code>AddCustom</code>，因此定义<code>AddCustom</code>类。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">namespace</span><span class="w"> </span><span class="nn">ops</span><span class="w"> </span><span class="p">{</span>
<span class="k">class</span><span class="w"> </span><span class="nc">AddCustom</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="k">public</span><span class="w"> </span><span class="n">OpDef</span><span class="w"> </span><span class="p">{</span>
<span class="k">public</span><span class="o">:</span>
<span class="w">    </span><span class="k">explicit</span><span class="w"> </span><span class="n">AddCustom</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">name</span><span class="p">)</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">OpDef</span><span class="p">(</span><span class="n">name</span><span class="p">)</span>
<span class="w">    </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 原型定义内容</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">};</span>
<span class="n">OP_ADD</span><span class="p">(</span><span class="n">AddCustom</span><span class="p">);</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// namespace ops</span>
</code></pre></div><p>这里有两个关键点：</p><ul><li>构造函数通过<code>OpDef(name)</code>初始化基类，后续的<code>Input</code>、<code>Output</code>、<code>Attr</code>、<code>AICore</code>等声明都写在构造函数中。</li><li>文件末尾通过<code>OP_ADD(AddCustom)</code>注册算子类型，编译工具据此识别算子原型，并生成aclnn接口、图模式原型等相关代码。</li></ul><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>OpType应采用大驼峰命名，首字符为大写英文字母，后续只能使用英文字母或数字，例如<code>AddCustom</code>。不要使用下划线、连字符、空格、中文或其他特殊字符。</p><p>自定义算子的OpType不能与内置算子重名。确定OpType后，可使用<a href="../../../appendix/optype_collector_tool.html">optype_collector工具</a>查询OpType信息并检测命名冲突。</p></div><h2 id="定义输入和输出">定义输入和输出<a class="header-anchor" href="#定义输入和输出">​</a></h2><p>输入输出定义来自功能设计阶段的结论。AddCustom有两个输入<code>x</code>、<code>y</code>，一个输出<code>z</code>，三个Tensor共同表达<code>z = x + y</code>的计算语义，因此都声明为<code>REQUIRED</code>。基础样例没有属性，输入输出声明就是原型定义中最先落地的接口内容。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;x&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;y&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">Output</span><span class="p">(</span><span class="s">&quot;z&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
</code></pre></div><p>输入输出参数说明如下：</p><table><thead><tr><th>原型项</th><th>参数</th><th>作用</th></tr></thead><tbody><tr><td><code>Input</code>/<code>Output</code></td><td>输入输出名称</td><td>声明输入输出名称，名称需要和功能设计中的参数名称一致。声明顺序会影响aclnn接口参数顺序和核函数（Kernel）入口参数顺序。</td></tr><tr><td><code>Input</code>/<code>Output</code></td><td><code>ParamType</code></td><td>声明参数提供方式。<code>REQUIRED</code>表示每次调用都必须提供，<code>OPTIONAL</code>表示部分场景可以省略，<code>DYNAMIC</code>表示数量随调用变化。</td></tr><tr><td><code>Input</code>/<code>Output</code></td><td><code>DataType</code></td><td>声明输入输出支持的dtype。多个dtype按列表顺序和format列表一一对应。</td></tr><tr><td><code>Input</code>/<code>Output</code></td><td><code>Format</code></td><td>声明输入输出支持的format。多个format按列表顺序和dtype列表一一对应。</td></tr></tbody></table><p>同一个输入或输出支持多组dtype/format时，<code>DataType</code>和<code>Format</code>列表需要按位置对应。例如下面的写法表示支持<code>DT_FLOAT16 + FORMAT_ND</code>、<code>DT_FLOAT + FORMAT_ND</code>和<code>DT_INT32 + FORMAT_ND</code>三组组合。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;x&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_INT32</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
</code></pre></div><ul><li><p>如果某个输入或输出的dtype或format能够和其他输入输出的组合自由搭配，可以使用<code>DataTypeList</code>或<code>FormatList</code>减少重复列举。以下两种写法表达相同组合关系。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="c1">// 方式一：逐项列出所有一一对应的组合。</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;x&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;y&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_INT32</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">Output</span><span class="p">(</span><span class="s">&quot;z&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_INT32</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>

<span class="c1">// 方式二：\`x\`固定支持\`DT_FLOAT16 + FORMAT_ND\`时，使用\`DataTypeList\`和\`FormatList\`表达\`x\`的支持集合。</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;x&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataTypeList</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">FormatList</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;y&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_INT32</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">Output</span><span class="p">(</span><span class="s">&quot;z&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_INT32</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
</code></pre></div></li><li><p>通过<a href="../../../../../api/Utils-API/prototype_register_management/OpParamDef/Follow.html">Follow接口</a>可以指定当前输入或输出的datatype、format和shape跟随前面已经定义过的输入。输出完全跟随某个输入时，Follow可以直接表达“输出与输入一致”的关系，通常无需再编写shape推导函数。Follow shape和<code>SetInferShape</code>不能混用；如果注册了<code>SetInferShape</code>，需要由推导函数完成所有输出的shape推导。</p><p>例如输出<code>y1</code>跟随输入<code>x1</code>时，<code>y1</code>的datatype、format和shape都会与<code>x1</code>保持一致：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;x1&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;x2&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT</span><span class="p">})</span>
<span class="w">    </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="k">this</span><span class="o">-&gt;</span><span class="n">Output</span><span class="p">(</span><span class="s">&quot;y1&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">Follow</span><span class="p">(</span><span class="s">&quot;x1&quot;</span><span class="p">);</span>
</code></pre></div></li></ul><h2 id="定义属性">定义属性<a class="header-anchor" href="#定义属性">​</a></h2><p>属性用于描述算子的配置项，例如维度、阈值、缩放系数、开关等。AddCustom基础样例只实现<code>z = x + y</code>，功能设计中已经确认没有额外属性，因此原型定义中没有<code>Attr</code>声明。</p><p>带属性的算子可以在构造函数中使用<code>Attr</code>定义。例如将AddCustom扩展为<code>z = x + alpha * y</code>时，可以增加<code>alpha</code>属性：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">this</span><span class="o">-&gt;</span><span class="n">Attr</span><span class="p">(</span><span class="s">&quot;alpha&quot;</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">AttrType</span><span class="p">(</span><span class="n">OPTIONAL</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">Float</span><span class="p">(</span><span class="mf">1.0</span><span class="p">);</span>
</code></pre></div><p><code>AttrType</code>描述属性是否必须提供，常用取值为<code>REQUIRED</code>和<code>OPTIONAL</code>。<code>Bool</code>、<code>Float</code>、<code>Int</code>等接口用于声明属性数据类型和默认值，具体说明请参考<a href="../../../../../api/Utils-API/prototype_register_management/OpAttrDef/OpAttrDef_functions.html">OpAttrDef</a>。</p><p>属性在原型中声明后，Host侧Tiling函数可以通过<code>context-&gt;GetAttrs()</code>获取属性值。核函数（Kernel）侧需要使用属性参与计算时，可以通过TilingData将属性值传递到核函数（Kernel）。属性传递方法见<a href="./tiling_data_attributes.html">通过TilingData传递属性信息</a>。</p><h2 id="图模式下注册输出shape和dtype推导函数">图模式下注册输出shape和dtype推导函数<a class="header-anchor" href="#图模式下注册输出shape和dtype推导函数">​</a></h2><p><code>DataType</code>和<code>Format</code>用于声明输入输出支持的dtype和format，不是图模式下的输出推导函数。算子仅通过aclnn单算子接口调用时，不需要注册输出shape和dtype推导函数。如果算子还需要支持图模式，可以通过<code>SetInferShape</code>和<code>SetInferDataType</code>注册输出shape和dtype推导函数。AddCustom的输出<code>z</code>与输入<code>x</code>具有相同shape和dtype，注册方式如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">this</span><span class="o">-&gt;</span><span class="n">SetInferShape</span><span class="p">(</span><span class="n">ge</span><span class="o">::</span><span class="n">InferShape</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">SetInferDataType</span><span class="p">(</span><span class="n">ge</span><span class="o">::</span><span class="n">InferDataType</span><span class="p">);</span>
</code></pre></div><p><a href="../../../../../api/Utils-API/prototype_register_management/OpDef/SetInferShape.html">SetInferShape</a>用于注册输出shape推导函数，<a href="../../../../../api/Utils-API/prototype_register_management/OpDef/SetInferDataType.html">SetInferDataType</a>用于注册输出dtype推导函数。注册后，框架在图模式下需要推导输出shape或dtype时会调用对应函数。</p><p>如果输出shape可以通过<code>Follow</code>表达，则优先使用<code>Follow</code>，无需再注册<code>SetInferShape</code>。例如，AddCustom的输出<code>z</code>与输入<code>x</code>具有相同shape时，可以在输出定义中通过<code>Follow(&quot;x&quot;, FollowType::SHAPE)</code>指定shape跟随关系。</p><p>本文只说明原型定义中如何关联推导函数。推导函数内部如何读取输入shape、设置输出shape、读取输入dtype和设置输出dtype，属于图模式开发和Host侧实现细节，见<a href="../../operator_graph_development/basic_development_flow.html">算子入图开发</a>。</p><h2 id="关联Host侧Tiling实现">关联Host侧Tiling实现<a class="header-anchor" href="#关联Host侧Tiling实现">​</a></h2><p>算子原型还需要关联Host侧Tiling函数。AddCustom样例中，Tiling函数名为<code>optiling::TilingFunc</code>，通过<code>AICore().SetTiling(...)</code>注册。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">this</span><span class="o">-&gt;</span><span class="n">AICore</span><span class="p">()</span>
<span class="w">    </span><span class="p">.</span><span class="n">SetTiling</span><span class="p">(</span><span class="n">optiling</span><span class="o">::</span><span class="n">TilingFunc</span><span class="p">);</span>
</code></pre></div><p><code>SetTiling</code>只负责建立原型和Tiling函数之间的调用关系。<code>TilingFunc</code>内部会读取输入shape等信息，计算核函数（Kernel）需要的运行参数，并写入TilingData。</p><p>TilingData字段设计、Tiling函数写法、workspace设置和<code>numBlocks</code>配置见<a href="./host_tiling_implementation.html">Host侧Tiling实现</a>。</p><h2 id="注册GenSimplifiedKey回调">注册GenSimplifiedKey回调<a class="header-anchor" href="#注册GenSimplifiedKey回调">​</a></h2><p>当算子需要依据运行时输入、输出或属性，从多份预编译核函数（Kernel）binary中快速选择一份时，可以注册<code>GenSimplifiedKey</code>回调。回调由算子开发者编写，只负责生成自定义simplified key片段；运行时框架负责在该片段前补齐算子类型和运行时公共维度，使用完整Key查找并选择对应的binary。</p><p>在已有Tiling注册的<code>AICore()</code>链式调用中增加<code>SetGenSimplifiedKey</code>即可：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">this</span><span class="o">-&gt;</span><span class="n">AICore</span><span class="p">()</span>
<span class="w">    </span><span class="p">.</span><span class="n">SetTiling</span><span class="p">(</span><span class="n">optiling</span><span class="o">::</span><span class="n">TilingFunc</span><span class="p">)</span>
<span class="w">    </span><span class="p">.</span><span class="n">SetGenSimplifiedKey</span><span class="p">(</span><span class="n">optiling</span><span class="o">::</span><span class="n">GenSimplifiedKeyFunc</span><span class="p">);</span>
</code></pre></div><p>该接口适用于同一算子存在多份二进制，且选择维度可由Host侧<code>TilingContext</code>读取的场景，例如输入dtype、format、shape分档或属性组合。回调生成的片段必须与编译配置JSON中每个<code>op_list</code>项的<code>simplified_key</code>严格对应；没有注册回调或不提供这类JSON时，保持原有binary匹配流程。</p><p>回调的具体写法、约束及其与运行时选择的边界见<a href="./gen_simplified_key.html">GenSimplifiedKey回调实现</a>。</p><h2 id="配置指定AI处理器的差异化配置">配置指定AI处理器的差异化配置<a class="header-anchor" href="#配置指定AI处理器的差异化配置">​</a></h2><p><code>AddConfig</code>为指定AI处理器设置差异化编译配置。</p><h3 id="使用OpAICoreConfig注册差异化配置">使用OpAICoreConfig注册差异化配置<a class="header-anchor" href="#使用OpAICoreConfig注册差异化配置">​</a></h3><p>当某个AI处理器的输入输出原型或其他编译配置与通用配置不同时，在算子原型构造函数中创建<code>OpAICoreConfig</code>，并通过<code>AddConfig(&quot;ascendxxx&quot;, config)</code>注册。&quot;ascendxxx&quot;填写规则请参考算子工程目录下编译配置项文件<code>CMakePresets.json</code>中的<code>ASCEND_COMPUTE_UNIT</code>字段，该字段取值在使用msOpGen创建工程时自动生成。</p><p><code>OpAICoreConfig</code>中未配置的输入输出继承<code>OpDef</code>中的定义；重新配置的同名输入输出覆盖通用定义。以下示例为指定AI处理器增加<code>DT_BF16</code>支持：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">namespace</span><span class="w"> </span><span class="nn">ops</span><span class="w"> </span><span class="p">{</span>
<span class="k">class</span><span class="w"> </span><span class="nc">AddCustom</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="k">public</span><span class="w"> </span><span class="n">OpDef</span><span class="w"> </span><span class="p">{</span>
<span class="k">public</span><span class="o">:</span>
<span class="w">    </span><span class="k">explicit</span><span class="w"> </span><span class="n">AddCustom</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">name</span><span class="p">)</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">OpDef</span><span class="p">(</span><span class="n">name</span><span class="p">)</span>
<span class="w">    </span><span class="p">{</span>
<span class="w">        </span><span class="c1">// 通用输入输出原型配置省略。</span>
<span class="w">        </span><span class="n">OpAICoreConfig</span><span class="w"> </span><span class="n">config</span><span class="p">;</span>
<span class="w">        </span><span class="n">config</span><span class="p">.</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;x&quot;</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_BF16</span><span class="p">})</span>
<span class="w">            </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="w">        </span><span class="n">config</span><span class="p">.</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;y&quot;</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_BF16</span><span class="p">})</span>
<span class="w">            </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="w">        </span><span class="n">config</span><span class="p">.</span><span class="n">Output</span><span class="p">(</span><span class="s">&quot;z&quot;</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_BF16</span><span class="p">})</span>
<span class="w">            </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="w">        </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">AICore</span><span class="p">().</span><span class="n">AddConfig</span><span class="p">(</span><span class="s">&quot;ascendxxx&quot;</span><span class="p">,</span><span class="w"> </span><span class="n">config</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">};</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// namespace ops</span>
</code></pre></div><h3 id="在独立文件中注册差异化配置">在独立文件中注册差异化配置<a class="header-anchor" href="#在独立文件中注册差异化配置">​</a></h3><p>也可以通过<code>REGISTER_OP_AICORE_CONFIG</code>在独立文件中注册差异化配置，便于按芯片或模块拆分维护。例如，在<code>op_host/add_custom_ascendxxx.cpp</code>中注册：</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="cp">#include</span><span class="w"> </span><span class="cpf">&quot;register/op_config_registry.h&quot;</span>

<span class="k">namespace</span><span class="w"> </span><span class="nn">ops</span><span class="w"> </span><span class="p">{</span>
<span class="n">REGISTER_OP_AICORE_CONFIG</span><span class="p">(</span><span class="n">AddCustom</span><span class="p">,</span><span class="w"> </span><span class="n">ascendxxx</span><span class="p">,</span><span class="w"> </span><span class="p">[]()</span><span class="w"> </span><span class="p">{</span>
<span class="w">    </span><span class="n">ops</span><span class="o">::</span><span class="n">OpAICoreConfig</span><span class="w"> </span><span class="n">config</span><span class="p">(</span><span class="s">&quot;ascendxxx&quot;</span><span class="p">);</span>
<span class="w">    </span><span class="n">config</span><span class="p">.</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;x&quot;</span><span class="p">)</span>
<span class="w">        </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">        </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">DT_BF16</span><span class="p">})</span>
<span class="w">        </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">,</span><span class="w"> </span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="w">    </span><span class="k">return</span><span class="w"> </span><span class="n">config</span><span class="p">;</span>
<span class="p">});</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// namespace ops</span>
</code></pre></div><div class="callout callout-note"><p class="callout-title"><svg class="callout-icon" viewBox="0 0 16 16" width="16" height="16"><path d="M0 8a8 8 0 1 1 16 0A8 8 0 0 1 0 8Zm8-6.5a6.5 6.5 0 1 0 0 13 6.5 6.5 0 0 0 0-13ZM6.5 7.75A.75.75 0 0 1 7.25 7h1a.75.75 0 0 1 .75.75v2.75h.25a.75.75 0 0 1 0 1.5h-2a.75.75 0 0 1 0-1.5h.25v-2h-.25a.75.75 0 0 1-.75-.75ZM8 6a1 1 0 1 1 0-2 1 1 0 0 1 0 2Z"></path></svg>说明</p><p>当两种方式为同一算子、同一AI处理器配置相同项时，在算子原型构造函数中通过<code>AICore().AddConfig(...)</code>注册的配置优先级高于在独立文件中通过<code>REGISTER_OP_AICORE_CONFIG</code>注册的配置。</p></div><h2 id="完整示例">完整示例<a class="header-anchor" href="#完整示例">​</a></h2><p>以下代码展示AddCustom的原型定义主体。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">namespace</span><span class="w"> </span><span class="nn">ops</span><span class="w"> </span><span class="p">{</span>
<span class="k">class</span><span class="w"> </span><span class="nc">AddCustom</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="k">public</span><span class="w"> </span><span class="n">OpDef</span><span class="w"> </span><span class="p">{</span>
<span class="k">public</span><span class="o">:</span>
<span class="w">    </span><span class="k">explicit</span><span class="w"> </span><span class="n">AddCustom</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="kt">char</span><span class="o">*</span><span class="w"> </span><span class="n">name</span><span class="p">)</span><span class="w"> </span><span class="o">:</span><span class="w"> </span><span class="n">OpDef</span><span class="p">(</span><span class="n">name</span><span class="p">)</span>
<span class="w">    </span><span class="p">{</span>
<span class="w">        </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;x&quot;</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">})</span>
<span class="w">            </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="w">        </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">Input</span><span class="p">(</span><span class="s">&quot;y&quot;</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">})</span>
<span class="w">            </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>
<span class="w">        </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">Output</span><span class="p">(</span><span class="s">&quot;z&quot;</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">ParamType</span><span class="p">(</span><span class="n">REQUIRED</span><span class="p">)</span>
<span class="w">            </span><span class="p">.</span><span class="n">DataType</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">DT_FLOAT16</span><span class="p">})</span>
<span class="w">            </span><span class="p">.</span><span class="n">Format</span><span class="p">({</span><span class="n">ge</span><span class="o">::</span><span class="n">FORMAT_ND</span><span class="p">});</span>

<span class="w">        </span><span class="k">this</span><span class="o">-&gt;</span><span class="n">AICore</span><span class="p">()</span>
<span class="w">            </span><span class="p">.</span><span class="n">SetTiling</span><span class="p">(</span><span class="n">optiling</span><span class="o">::</span><span class="n">TilingFunc</span><span class="p">);</span>
<span class="w">    </span><span class="p">}</span>
<span class="p">};</span>
<span class="n">OP_ADD</span><span class="p">(</span><span class="n">AddCustom</span><span class="p">);</span>
<span class="p">}</span><span class="w"> </span><span class="c1">// namespace ops</span>
</code></pre></div><h2 id="相关文档">相关文档<a class="header-anchor" href="#相关文档">​</a></h2><ul><li><a href="./operator_function_design.html">算子功能设计</a>：了解如何确定算子的输入输出、属性和Host侧Tiling设计。</li><li><a href="./host_tiling_implementation.html">Host侧Tiling实现</a>：了解TilingData定义、Tiling函数编写和<code>SetTiling</code>关联关系。</li><li><a href="./gen_simplified_key.html">GenSimplifiedKey回调实现</a>：了解如何为预编译核函数（Kernel）binary生成自定义simplified key片段。</li><li><a href="./kernel_operator_implementation.html">核函数（Kernel）侧算子实现</a>：了解核函数（Kernel）入口格式、参数顺序和TilingData读取方式。</li><li><a href="../appendix/naming_conversion_table.html">命名转换规则对照表</a>：了解OpType、核函数（Kernel）入口和aclnn接口之间的命名转换关系。</li></ul></article></div>`,1)])])}const T=a(l,[["render",e]]);export{g as __pageData,T as default};
